<div class="page-heading"><div><span class="eyebrow dark">Execução comercial</span><h1>Pipeline comercial</h1><p><?= (int)$total ?> oportunidade(s) distribuída(s) por etapa.</p></div><div class="heading-actions"><a class="button button-secondary" href="<?= url('/leads') ?>">Ver cadastros</a><a class="button button-primary" href="<?= url('/leads/create') ?>">+ Nova empresa</a></div></div>
<div class="pipeline-board"><?php foreach($stages as $stage): ?><section class="pipeline-column"><header><span><?= e($stage) ?></span><b><?= count($columns[$stage]) ?></b></header><div class="pipeline-stack"><?php foreach($columns[$stage] as $lead): ?><article class="pipeline-card"><div class="pipeline-card-top"><span class="source-label"><?= e($lead['origem']) ?></span><a href="<?= url('/leads/edit?id='.(int)$lead['id']) ?>">Editar</a></div><h3><a class="entity-link" href="<?= url('/leads/view?id='.(int)$lead['id']) ?>"><?= e($lead['nome_empresa']) ?></a></h3><p><?= e($lead['nome'] ?: $lead['email']) ?></p><small><?= e($lead['telefone']) ?></small><form method="post" action="<?= url('/pipeline/status') ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$lead['id'] ?>"><label>Mover para<select name="status" data-auto-submit><?php foreach($stages as $option): ?><option <?= $option===$lead['status']?'selected':'' ?>><?= e($option) ?></option><?php endforeach; ?></select></label></form></article><?php endforeach; ?><?php if($columns[$stage]===[]): ?><div class="pipeline-empty">Nenhuma oportunidade nesta etapa.</div><?php endif; ?></div></section><?php endforeach; ?></div>
